const forbiddenPorts=new Set(['36994','4180','4280']);
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const pause=ms=>new Promise(accept=>setTimeout(accept,ms));
const runId='a2-preview-'+randomUUID(),root=join(repository,'evidence/apps-a2-20261007/formal-preview',runId);
mkdirSync(root,{recursive:true});
const executions=[];
const put=(name,value)=>{const path=join(root,name);mkdirSync(dirname(path),{recursive:true});writeFileSync(path,typeof value==='string'||Buffer.isBuffer(value)?value:JSON.stringify(value,null,2),{flag:'wx'});return evidenceFile(path);};
function localUrl(value){const url=new URL(value);assert.equal(url.protocol,'http:');assert.equal(url.hostname,'127.0.0.1');assert.ok(!forbiddenPorts.has(url.port),'Production ports are forbidden');return url;}
async function localFetch(value,options){localUrl(value);return fetch(value,options);}
async function cli(entry,input,label){
 const request=put(label+'-request.json',input),args=[join(installed,'lib',entry),request.path],startedAt=new Date().toISOString();
 const child=spawn(process.execPath,args,{cwd:repository,windowsHide:true,stdio:['ignore','pipe','pipe']});let stdout='',stderr='';
 child.stdout.on('data',bytes=>stdout+=bytes);child.stderr.on('data',bytes=>stderr+=bytes);
 const exitCode=await new Promise((accept,reject)=>{child.once('error',reject);child.once('close',accept);});
 const log=put(label+'-process.json',{executable:process.execPath,args,pid:child.pid,startedAt,finishedAt:new Date().toISOString(),exitCode,stdout,stderr});
 const result=JSON.parse(stdout.trim().split(/\r?\n/).at(-1)),observed={entry,label,...result,exitCode,log,request};executions.push(observed);return observed;
}

async function isolatedBrowser(label){
 const server=createPortServer();await new Promise(accept=>server.listen(0,'127.0.0.1',accept));const port=server.address().port;await new Promise(accept=>server.close(accept));assert.ok(!forbiddenPorts.has(String(port)));
 const profile=join(root,'browser-'+label);mkdirSync(profile);
 const child=spawn(browser,['--headless=new','--disable-gpu','--disable-background-networking','--disable-component-update','--disable-extensions','--no-first-run','--no-default-browser-check',`--remote-debugging-port=${port}`,`--user-data-dir=${profile}`,'about:blank'],{windowsHide:true,stdio:['ignore','ignore','pipe']});
 let stderr='',socket,sequence=0;child.stderr.on('data',bytes=>stderr+=bytes);const pending=new Map(),events=[];
 const command=(method,params={})=>new Promise((accept,reject)=>{const id=++sequence,timer=setTimeout(()=>{pending.delete(id);reject(new Error('CDP timeout '+method));},10000);pending.set(id,{accept:value=>{clearTimeout(timer);accept(value);},reject:error=>{clearTimeout(timer);reject(error);}});socket.send(JSON.stringify({id,method,params}));});
 const evaluate=async expression=>{const result=await command('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(result.exceptionDetails)throw Error(result.exceptionDetails.exception?.description??result.exceptionDetails.text);return result.result.value;};
 try{
  let pages;for(let n=0;n<100;n++){try{pages=await localFetch(`http://127.0.0.1:${port}/json/list`).then(response=>response.json());if(pages.length)break;}catch{}await pause(100);}
  assert.ok(pages?.length,'Fresh browser CDP unavailable');socket=new WebSocket(pages.find(page=>page.type==='page').webSocketDebuggerUrl);
  await new Promise((accept,reject)=>{socket.addEventListener('open',accept,{once:true});socket.addEventListener('error',reject,{once:true});});
  socket.addEventListener('message',event=>{const item=JSON.parse(event.data),request=pending.get(item.id);if(request){pending.delete(item.id);item.error?request.reject(new Error(item.error.message)):request.accept(item.result);}else events.push(item);});
  await command('Page.enable');await command('Runtime.enable');await command('Network.enable');
  return {command,evaluate,events,async navigate(url,width=1040){localUrl(url);await command('Emulation.setDeviceMetricsOverride',{width,height:900,deviceScaleFactor:1,mobile:false});await command('Page.navigate',{url});},async until(expression){for(let n=0;n<100;n++){if(await evaluate(expression))return;await pause(100);}throw Error('Browser observation deadline: '+expression);},async screenshot(name){const captured=await command('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});const file=put(name,Buffer.from(captured.data,'base64'));assert.equal(readFileSync(file.path).subarray(1,4).toString(),'PNG');assert.equal(readFileSync(file.path).readUInt32BE(16),1040);return file;},async close(){await command('Browser.close').catch(()=>{});for(let n=0;n<20&&child.exitCode===null;n++)await pause(100);if(child.exitCode===null)child.kill();socket.close();if(child.exitCode===null)await new Promise(accept=>{const timer=setTimeout(accept,2000);child.once('close',()=>{clearTimeout(timer);accept();});});let spawnedPidPresent;try{process.kill(child.pid,0);spawnedPidPresent=true;}catch{spawnedPidPresent=false;}put('browser-'+label+'-process.json',{executable:browser,pid:child.pid,profile,exitCode:child.exitCode,signalCode:child.signalCode,spawnedPidPresent,stderr});assert.equal(spawnedPidPresent,false,'Owned browser process must stop');}};
 }catch(error){socket?.close();child.kill();throw error;}
}

