 const candidateArchive=join(repository,'artifacts/dsh-plugin-apps-bundle-1.0.0-candidate.10.tgz'),packageManifest=JSON.parse(readFileSync(join(repository,'evidence/apps-a2-20261007/candidates/1.0.0-candidate.10/package-manifest.json'),'utf8'));
