 async function prepared(label,options={}){const begin=authoring.begin(sessionId,{mode:'new',title:label,workspacePath:join(root,'workspaces',label)});writeProject(begin.draft.workspacePath,options);const build=await cli('apps-authoring-build.js',{attemptId:begin.attempt.attemptId,epoch:begin.attempt.epoch,sourceRevision:begin.attempt.sourceRevision,workspacePath:begin.draft.workspacePath,command:[process.execPath,'build.mjs'],evidenceRoot:runner.root,archiveRoot:sources.directory},label+'-build');assert.equal(build.exitCode,0);const receipt=await authoring.recordBuild(sessionId,{attemptId:begin.attempt.attemptId,epoch:begin.attempt.epoch,reportRef:build.reportRef});receipts.push(put(label+'-build-receipt.json',receipt));return {begin,build,receipt};}
