  const host=await startAuthoringPreview({sources,buildId:first.receipt.archiveBuildId,mode:'fixture',data:fixtureData,context:fixtureContext});let page;
  try{observations.v2Http=await resourceManifest(host,sources,first.receipt.archiveBuildId,'v2-positive');page=await isolatedBrowser('v2-transcript');await page.navigate(host.url);await page.until("Boolean(document.querySelector('iframe')?.contentWindow.__fixture?.done)");const state=await page.evaluate('window.__APPS_PREVIEW');const inner=await page.evaluate("document.querySelector('iframe').contentWindow.__fixture");assert.equal(state.bridgeReady,true);assert.equal(state.dataRead,true);assert.equal(inner.hello.protocolVersion,'2.0');assert.deepEqual(inner.data,fixtureData);assert.deepEqual(inner.context,fixtureContext);assert.deepEqual(state.events.map(event=>event.request.method??event.request.type),['hello','getData','getContext','resize']);assert.ok(state.events.every(event=>!event.response.error));const serverState=await localFetch(host.url+'/status').then(response=>response.json());observations.v2Bridge=put('v2-positive/bridge-transcript.json',{carrier:'production startAuthoringPreview source helper',buildId:first.receipt.archiveBuildId,browserState:state,componentState:inner,serverState,networkEvents:page.events.filter(event=>event.method.startsWith('Network.')),pageErrors:page.events.filter(event=>event.method==='Runtime.exceptionThrown'),screenshot:await page.screenshot('v2-positive/bridge.png')});}finally{await page?.close();await host.close();}
  const oldReport=preview.reportRef,next=await prepared('different-build',{revision:2});assert.notEqual(next.receipt.archiveBuildId,first.receipt.archiveBuildId);
